package rotasegura.gui;
import rotasegura.service.Locadora;
import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.awt.event.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class Tela extends JFrame {
 private final Locadora s; private final JTable[] tabelas=new JTable[3];
 private final String[][] colunas={{"CPF","Nome","Telefone"},{"Placa","Marca","Modelo","Ano","Categoria","Disponível"},{"Contrato","CPF","Placa","Dias","Total (R$)","Status","Abertura","Fechamento"}};
 interface Acao{void run()throws Exception;}
 public Tela(Locadora s)throws Exception{super("Rota Segura | Gestão de locações");this.s=s;setSize(1100,650);setLocationRelativeTo(null);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){try{s.close();dispose();}catch(Exception x){erro(x);}}});
 JPanel header=new JPanel(new BorderLayout());header.setBackground(new Color(19,43,65));header.setBorder(BorderFactory.createEmptyBorder(20,24,20,24));JLabel titulo=new JLabel("ROTA SEGURA   /   Gestão de locações");titulo.setForeground(Color.WHITE);titulo.setFont(new Font("SansSerif",Font.BOLD,24));header.add(titulo);add(header,BorderLayout.NORTH);
 JTabbedPane tabs=new JTabbedPane();String[] nomes={"Clientes","Veículos","Locações"};for(int i=0;i<3;i++)tabs.addTab(nomes[i],painel(i));add(tabs);refresh();}
 private void erro(Exception e){JOptionPane.showMessageDialog(this,e instanceof NumberFormatException?"Informe um número inteiro válido.":e.getMessage(),"Não foi possível concluir",JOptionPane.ERROR_MESSAGE);}
 private void executar(Acao a){try{a.run();refresh();}catch(Exception e){erro(e);}}
 private void botao(JPanel p,String nome,Acao a){JButton b=new JButton(nome);b.addActionListener(e->executar(a));p.add(b);}
 private JPanel painel(int i){JPanel p=new JPanel(new BorderLayout(8,8));p.setBorder(BorderFactory.createEmptyBorder(14,14,14,14));JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));JTextField busca=new JTextField(20);top.add(new JLabel("Consultar:"));top.add(busca);JTable t=new JTable();t.setRowHeight(28);t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);tabelas[i]=t;busca.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){void filtrar(){if(t.getRowSorter() instanceof TableRowSorter)((TableRowSorter<?>)t.getRowSorter()).setRowFilter(RowFilter.regexFilter("(?i)"+java.util.regex.Pattern.quote(busca.getText())));}public void insertUpdate(javax.swing.event.DocumentEvent e){filtrar();}public void removeUpdate(javax.swing.event.DocumentEvent e){filtrar();}public void changedUpdate(javax.swing.event.DocumentEvent e){filtrar();}});botao(top,"Atualizar",()->{});p.add(top,BorderLayout.NORTH);p.add(new JScrollPane(t));JPanel b=new JPanel(new FlowLayout(FlowLayout.LEFT));botao(b,i==2?"Abrir locação":"Cadastrar",()->form(i,false));botao(b,"Editar",()->form(i,true));botao(b,i==2?"Cancelar locação":"Excluir",()->excluir(i));if(i==2){botao(b,"Devolver / fechar",()->fechar());botao(b,"Resumo / relatório",()->relatorio());}p.add(b,BorderLayout.SOUTH);return p;}
 private void refresh()throws Exception{java.util.List<java.util.List<Object[]>> dados=Arrays.asList(s.clientes(),s.veiculos(),s.locacoes());for(int i=0;i<3;i++){JTable t=tabelas[i];RowFilter<?,?> filtro=t.getRowSorter() instanceof TableRowSorter?((TableRowSorter<?>)t.getRowSorter()).getRowFilter():null;DefaultTableModel m=new DefaultTableModel(colunas[i],0){public boolean isCellEditable(int r,int c){return false;}};for(Object[] a:dados.get(i)){if(i==1)a[5]=Boolean.TRUE.equals(a[5])?"Sim":"Não";m.addRow(a);}t.setModel(m);TableRowSorter<DefaultTableModel> sorter=new TableRowSorter<>(m);t.setRowSorter(sorter);if(filtro!=null)sorter.setRowFilter((RowFilter)filtro);}}
 private Object[] selecionado(int i){JTable t=tabelas[i];int r=t.getSelectedRow();if(r<0)throw new IllegalArgumentException("Selecione um registro na tabela.");r=t.convertRowIndexToModel(r);Object[] a=new Object[t.getColumnCount()];for(int j=0;j<a.length;j++)a[j]=t.getModel().getValueAt(r,j);return a;}
 private boolean dialog(String titulo,String[] labels,JComponent... campos){JPanel p=new JPanel(new GridLayout(0,2,8,8));for(int i=0;i<labels.length;i++){p.add(new JLabel(labels[i]));p.add(campos[i]);}return JOptionPane.showConfirmDialog(this,p,titulo,JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE)==JOptionPane.OK_OPTION;}
 private JTextField campo(Object o){return new JTextField(o==null?"":o.toString(),22);}
 private void form(int i,boolean edit)throws Exception{Object[] a=edit?selecionado(i):new Object[8];if(i==0){JTextField cpf=campo(a[0]),nome=campo(a[1]),tel=campo(a[2]);cpf.setEditable(!edit);if(dialog("Cliente",new String[]{"CPF","Nome","Telefone"},cpf,nome,tel))s.cliente(edit,cpf.getText(),nome.getText(),tel.getText());}else if(i==1){JTextField placa=campo(a[0]),marca=campo(a[1]),modelo=campo(a[2]),ano=campo(a[3]);placa.setEditable(!edit);JComboBox<String> cat=new JComboBox<>(new String[]{"Popular","Sedan","SUV"});if(edit)cat.setSelectedItem(a[4]);if(dialog("Veículo",new String[]{"Placa","Marca","Modelo","Ano","Categoria"},placa,marca,modelo,ano,cat))s.veiculo(edit,placa.getText(),marca.getText(),modelo.getText(),ano.getText(),cat.getSelectedItem().toString());}else if(edit){JTextField dias=campo(a[3]);if(dialog("Editar contrato",new String[]{"Dias"},dias))s.editar(((Number)a[0]).intValue(),Locadora.dias(dias.getText()));}else{JComboBox<String> cpf=new JComboBox<>(),placa=new JComboBox<>();for(Object[] c:s.clientes())cpf.addItem(c[0].toString());for(Object[] v:s.veiculos())if(Boolean.TRUE.equals(v[5]))placa.addItem(v[0].toString());if(cpf.getItemCount()==0||placa.getItemCount()==0)throw new IllegalArgumentException("Cadastre um cliente e disponibilize um veículo.");JTextField dias=campo(1);if(dialog("Nova locação",new String[]{"CPF","Placa","Dias"},cpf,placa,dias))s.abrir(cpf.getSelectedItem().toString(),placa.getSelectedItem().toString(),Locadora.dias(dias.getText()));}}
 private void excluir(int i)throws Exception{Object[] a=selecionado(i);if(JOptionPane.showConfirmDialog(this,"Confirma a operação?","Confirmação",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;if(i==0)s.excluirCliente(a[0].toString());else if(i==1)s.excluirVeiculo(a[0].toString());else s.cancelar(((Number)a[0]).intValue());}
 private void fechar()throws Exception{Object[] a=selecionado(2);int id=((Number)a[0]).intValue();if(!"ABERTA".equals(a[5]))throw new IllegalArgumentException("Contrato já encerrado.");JTextField d=campo(a[3]);if(!dialog("Devolução",new String[]{"Dias efetivos"},d))return;int dias=Locadora.dias(d.getText());if(JOptionPane.showConfirmDialog(this,s.resumo(id,dias)+"\n\nConfirmar encerramento?","Resumo do fechamento",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){s.fechar(id,dias);exportar(s.resumo(id,dias));}}
 private void relatorio()throws Exception{Object[] a=selecionado(2);exportar(s.resumo(((Number)a[0]).intValue(),((Number)a[3]).intValue()));}
 private void exportar(String texto)throws Exception{JTextArea area=new JTextArea(texto,12,45);area.setEditable(false);if(JOptionPane.showConfirmDialog(this,new JScrollPane(area),"Resumo — salvar relatório TXT?",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){JFileChooser f=new JFileChooser();f.setSelectedFile(new java.io.File("contrato.txt"));if(f.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)Files.write(f.getSelectedFile().toPath(),texto.getBytes(StandardCharsets.UTF_8));}}
}
